1	@import "tailwindcss";
2	
3	/* =====================================================================
4	   HEARD — Design tokens (ported from the design system colors_and_type.css)
5	   Warm, trustworthy, accessible-first. Body floor 18px. AA floor, AAA body.
6	   Fonts (Lora display + Nunito Sans body) are loaded via next/font in
7	   app/layout.tsx and exposed as --font-lora / --font-nunito-sans.
8	   ===================================================================== */
9	
10	@theme {
11	  /* ---- Color: brand palette (exact tokens from brief) ------------- */
12	  --color-bg: #fbf7f2; /* warm off-white page background */
13	  --color-surface: #ffffff; /* cards, sheets */
14	  --color-surface-sunk: #f4eee5; /* recessed wells, track backgrounds */
15	
16	  --color-ink: #2a2622; /* primary text (warm near-black) */
17	  --color-ink-soft: #6b6259; /* secondary text */
18	  --color-ink-faint: #948b81; /* tertiary / placeholder */
19	
20	  --color-primary: #136f63; /* calm teal — trust; primary buttons */
21	  --color-primary-dark: #0e5249; /* hover / active */
22	  --color-primary-tint: #e4efec; /* teal wash — selected chips, fills */
23	
24	  --color-accent: #e08a3c; /* warm amber — tips, gentle highlights */
25	  --color-accent-dark: #c4732c; /* amber hover / active */
26	  --color-accent-tint: #fbebd9; /* amber wash */
27	  --color-accent-strong: #8a4f15; /* darker amber — AA text on accent-tint (≥4.5:1) */
28	
29	  --color-success: #2e7d5b; /* available / positive (pair w/ text) */
30	  --color-success-tint: #e3f0ea;
31	  --color-success-strong: #236449; /* darker green — AA text on success-tint (≥4.5:1) */
32	  --color-alert: #b23a2e; /* errors / safety (pair w/ text) */
33	  --color-alert-tint: #f7e6e3;
34	
35	  --color-border: #ece3d8; /* hairlines, dividers */
36	  --color-border-strong: #d9ccbc; /* input borders, stronger separation */
37	  --color-focus: #1b6fb0; /* high-visibility focus ring (3px) */
38	
39	  /* ---- Type families --------------------------------------------- */
40	  --font-display: var(--font-lora), Georgia, "Times New Roman", serif;
41	  --font-body: var(--font-nunito-sans), system-ui, -apple-system, sans-serif;
42	
43	  /* ---- Type scale (rem from 16px root). Body floor = 18px -------- */
44	  --text-xs: 0.875rem; /* 14px — meta / fine print */
45	  --text-sm: 1rem; /* 16px — labels, secondary */
46	  --text-base: 1.125rem; /* 18px — BODY MINIMUM */
47	  --text-lg: 1.25rem; /* 20px — large body / lead */
48	  --text-h3: 1.5rem; /* 24px */
49	  --text-h2: 1.875rem; /* 30px */
50	  --text-h1: 2.375rem; /* 38px */
51	  --text-display: 2.875rem; /* 46px */
52	
53	  --leading-tight: 1.2;
54	  --leading-snug: 1.35;
55	  --leading-body: 1.6;
56	
57	  /* ---- Radii ----------------------------------------------------- */
58	  --radius-sm: 8px;
59	  --radius-btn: 12px;
60	  --radius-card: 16px;
61	  --radius-lg: 24px;
62	  --radius-pill: 999px;
63	
64	  /* ---- Shadows — soft, low, warm --------------------------------- */
65	  --shadow-xs: 0 1px 2px rgba(42, 38, 34, 0.05);
66	  --shadow-sm: 0 2px 8px rgba(42, 38, 34, 0.06);
67	  --shadow-md: 0 6px 20px rgba(42, 38, 34, 0.08);
68	  --shadow-lg: 0 14px 40px rgba(42, 38, 34, 0.12);
69	
70	  /* ---- Layout ----------------------------------------------------- */
71	  /* Desktop-first. The main section spans 85% of the viewport, capped so text
72	     lines stay readable for the low-vision audience on very large monitors.
73	     Exposed as the `app` container size → utilities `max-w-app` / `w-app`. */
74	  --container-app: 1500px;
75	
76	  /* ---- Min interactive target ------------------------------------ */
77	  --tap-min: 48px;
78	
79	  /* ---- Motion (gentle; respect reduced-motion) ------------------- */
80	  --ease-warm: cubic-bezier(0.33, 0.1, 0.25, 1);
81	}
82	
83	/* =====================================================================
84	   SEMANTIC ELEMENT DEFAULTS
85	   In @layer base so Tailwind utilities (e.g. text-surface on a heading over
86	   the teal panel) can override these element defaults — unlayered rules would
87	   otherwise win over layered utilities in the cascade.
88	   ===================================================================== */
89	
90	@layer base {
91	  html {
92	    font-size: 16px;
93	  }
94	
95	  body {
96	    background: var(--color-bg);
97	    color: var(--color-ink);
98	    font-family: var(--font-body);
99	    font-size: var(--text-base);
100	    line-height: var(--leading-body);
101	    font-weight: 400;
102	    -webkit-font-smoothing: antialiased;
103	    text-rendering: optimizeLegibility;
104	  }
105	
106	  h1,
107	  h2,
108	  h3,
109	  h4 {
110	    font-family: var(--font-display);
111	    /* Inherit color (ink by default) so a coloured parent — e.g. the teal auth
112	       panel with text-surface — recolours headings without a specificity fight. */
113	    color: inherit;
114	    line-height: var(--leading-tight);
115	    text-wrap: balance;
116	    margin: 0;
117	  }
118	  h1 {
119	    font-size: var(--text-h1);
120	    font-weight: 700;
121	    letter-spacing: -0.01em;
122	  }
123	  h2 {
124	    font-size: var(--text-h2);
125	    font-weight: 700;
126	    letter-spacing: -0.01em;
127	  }
128	  h3 {
129	    font-size: var(--text-h3);
130	    font-weight: 700;
131	  }
132	
133	  p {
134	    margin: 0;
135	    text-wrap: pretty;
136	  }
137	
138	  a {
139	    color: var(--color-primary);
140	    text-underline-offset: 3px;
141	  }
142	  a:hover {
143	    color: var(--color-primary-dark);
144	  }
145	}
146	
147	/* ---- Universal visible focus — the single most important rule ----- */
148	:where(
149	    a,
150	    button,
151	    input,
152	    select,
153	    textarea,
154	    [tabindex],
155	    [role="button"],
156	    [role="tab"],
157	    [role="switch"]
158	  ):focus-visible {
159	  outline: none;
160	  box-shadow: 0 0 0 3px var(--color-focus);
161	  border-radius: var(--radius-sm);
162	}
163	
164	/* Gentle waveform used by the voice player; static under reduced motion. */
165	@keyframes wf {
166	  from {
167	    transform: scaleY(0.4);
168	  }
169	  to {
170	    transform: scaleY(1);
171	  }
172	}
173	
174	@media (prefers-reduced-motion: reduce) {
175	  *,
176	  *::before,
177	  *::after {
178	    animation-duration: 0.001ms !important;
179	    animation-iteration-count: 1 !important;
180	    transition-duration: 0.001ms !important;
181	  }
182	}
