1	import * as React from "react";
2	import { type LucideIcon } from "lucide-react";
3	
4	type Variant = "primary" | "amber" | "ghost" | "danger" | "quiet";
5	
6	const VARIANTS: Record<Variant, string> = {
7	  primary: "bg-primary text-surface hover:bg-primary-dark border-transparent",
8	  amber: "bg-accent text-surface hover:bg-accent-dark border-transparent",
9	  ghost:
10	    "bg-surface text-primary border-border-strong hover:bg-primary-tint",
11	  danger: "bg-alert text-surface hover:brightness-95 border-transparent",
12	  quiet:
13	    "bg-transparent text-primary underline underline-offset-[3px] hover:text-primary-dark border-transparent min-h-0 px-1.5 py-2",
14	};
15	
16	export interface ButtonProps
17	  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
18	  variant?: Variant;
19	  /** Optional leading icon. Always paired with the button's text label. */
20	  icon?: LucideIcon;
21	  full?: boolean;
22	}
23	
24	/**
25	 * Accessible button primitive. ≥48px tap target, visible focus ring (from
26	 * globals.css), text label always present — never icon-only (see SPEC §10).
27	 */
28	export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
29	  function Button(
30	    { variant = "primary", icon: Icon, full, className = "", children, type = "button", ...rest },
31	    ref,
32	  ) {
33	    const isQuiet = variant === "quiet";
34	    return (
35	      <button
36	        ref={ref}
37	        type={type}
38	        className={[
39	          "inline-flex items-center justify-center gap-2.5 whitespace-nowrap rounded-btn border font-body font-bold leading-tight",
40	          "text-base transition-colors duration-200 ease-[cubic-bezier(0.33,0.1,0.25,1)]",
41	          "disabled:cursor-not-allowed disabled:opacity-60",
42	          isQuiet ? "" : "min-h-12 px-[22px] py-2.5",
43	          full ? "w-full" : "",
44	          VARIANTS[variant],
45	          className,
46	        ]
47	          .filter(Boolean)
48	          .join(" ")}
49	        {...rest}
50	      >
51	        {Icon ? <Icon size={20} strokeWidth={2} aria-hidden="true" /> : null}
52	        {children}
53	      </button>
54	    );
55	  },
56	);
