1	"use client";
2	
3	import * as React from "react";
4	import { Play, Pause } from "lucide-react";
5	import { t } from "@/lib/i18n";
6	import { useToast } from "@/components/ui/Toast";
7	
8	export interface VoicePlayerProps {
9	  name: string;
10	  /** Transcript text shown (the "voice intro" content). */
11	  intro: string;
12	  /** Larger layout with visible transcript (used on the profile screen). */
13	  big?: boolean;
14	  /** Optional signed URL to real audio. When absent, playback is simulated. */
15	  audioUrl?: string | null;
16	}
17	
18	/** Decorative animated bars; reduced to static under prefers-reduced-motion. */
19	function Waveform() {
20	  const bars = [8, 18, 12, 20, 9, 15, 22, 11];
21	  return (
22	    <span
23	      aria-hidden="true"
24	      className="inline-flex h-[22px] items-center gap-[3px]"
25	    >
26	      {bars.map((h, i) => (
27	        <span
28	          key={i}
29	          className="w-[3px] rounded-[2px] bg-accent"
30	          style={{
31	            height: h,
32	            animation: `wf 0.9s var(--ease-warm) ${i * 0.08}s infinite alternate`,
33	          }}
34	        />
35	      ))}
36	    </span>
37	  );
38	}
39	
40	/**
41	 * Voice-intro player — the focal element of discovery. Plays real audio when a
42	 * signed URL is provided, otherwise simulates playback. Always shows a
43	 * transcript so the content is fully available to screen-reader users.
44	 */
45	export function VoicePlayer({ name, intro, big, audioUrl }: VoicePlayerProps) {
46	  const [playing, setPlaying] = React.useState(false);
47	  const { announce } = useToast();
48	  const audioRef = React.useRef<HTMLAudioElement | null>(null);
49	
50	  const toggle = () => {
51	    const next = !playing;
52	    setPlaying(next);
53	    if (audioUrl && audioRef.current) {
54	      if (next) void audioRef.current.play();
55	      else audioRef.current.pause();
56	    }
57	    announce(
58	      next ? t("ui.announcePlaying", { name }) : t("ui.announcePaused"),
59	    );
60	  };
61	
62	  const diameter = big ? 64 : 48;
63	
64	  return (
65	    <div
66	      className={[
67	        "flex gap-3.5 rounded-card border border-border bg-surface shadow-sm",
68	        big ? "flex-col items-stretch p-4" : "flex-row items-center p-3",
69	      ].join(" ")}
70	    >
71	      <div className="flex min-w-0 flex-1 items-center gap-3.5">
72	        <button
73	          type="button"
74	          onClick={toggle}
75	          aria-label={
76	            playing
77	              ? t("ui.pauseVoiceIntro", { name })
78	              : t("ui.playVoiceIntro", { name })
79	          }
80	          aria-pressed={playing}
81	          className="grid flex-none place-items-center rounded-pill bg-primary text-surface hover:bg-primary-dark aria-pressed:bg-primary-dark"
82	          style={{ width: diameter, height: diameter }}
83	        >
84	          {playing ? (
85	            <Pause size={big ? 28 : 22} strokeWidth={2} aria-hidden="true" />
86	          ) : (
87	            <Play size={big ? 28 : 22} strokeWidth={2} aria-hidden="true" />
88	          )}
89	        </button>
90	        <div className="min-w-0 flex-1">
91	          <div className="text-base font-bold text-ink">
92	            {t("ui.voiceIntroOf", { name })}
93	          </div>
94	          <div className="flex items-center gap-2 text-sm text-ink-soft">
95	            {playing ? (
96	              <>
97	                <Waveform />
98	                <span>{t("ui.playingNow")}</span>
99	              </>
100	            ) : (
101	              <span>{t("ui.tapToListen")}</span>
102	            )}
103	          </div>
104	        </div>
105	      </div>
106	      {big ? (
107	        <p className="text-base leading-snug text-ink">
108	          <span className="mb-0.5 block text-xs font-bold text-ink-soft">
109	            {t("ui.transcript")}
110	          </span>
111	          {intro}
112	        </p>
113	      ) : null}
114	      {audioUrl ? (
115	        <audio
116	          ref={audioRef}
117	          src={audioUrl}
118	          onEnded={() => setPlaying(false)}
119	          className="sr-only"
120	        />
121	      ) : null}
122	    </div>
123	  );
124	}
