15	/** Animated speaking bars; static when muted and under reduced motion (CSS). */
16	function CallWaveform({ active }: { active: boolean }) {
17	  const bars = [14, 28, 20, 34, 16, 30, 24, 38, 18, 26];
18	  return (
19	    <span aria-hidden="true" className="flex h-10 items-center gap-1.5">
20	      {bars.map((h, i) => (
21	        <span
22	          key={i}
23	          className="w-1.5 rounded-full bg-accent"
24	          style={{
25	            height: active ? h : 6,
26	            // Delay folded into the shorthand — don't mix `animation` with a
27	            // separate `animationDelay` (React warns on conflicting updates).
28	            animation: active
29	              ? `wf 0.9s var(--ease-warm) ${i * 0.07}s infinite alternate`
30	              : "none",
31	          }}
32	        />
33	      ))}
34	    </span>
35	  );
