38	export interface CallStageProps {
39	  name: string;
40	  avatarColor: string;
41	  /** Called with the elapsed seconds (the timer is the source of truth). */
42	  onEnd: (elapsedSeconds: number) => Promise<void>;
43	  endLabel: string;
44	}
45	
46	export function CallStage({ name, avatarColor, onEnd, endLabel }: CallStageProps) {
47	  const { announce } = useToast();
48	  const [elapsed, setElapsed] = React.useState(0);
49	  const [muted, setMuted] = React.useState(false);
50	  const [captionsOn, setCaptionsOn] = React.useState(false);
51	  const [ending, setEnding] = React.useState(false);
52	  const elapsedRef = React.useRef(0);
53	
54	  React.useEffect(() => {
55	    announce(t("session.connectedAnnounce"), true);
56	    const id = window.setInterval(() => {
57	      elapsedRef.current += 1;
58	      setElapsed(elapsedRef.current);
59	    }, 1000);
60	    return () => window.clearInterval(id);
61	  }, [announce]);
62	
63	  async function end() {
64	    setEnding(true);
65	    announce(t("session.endedAnnounce"), true);
66	    await onEnd(elapsedRef.current);
67	  }
68	
69	  return (
70	    <div className="mx-auto flex w-full max-w-2xl flex-col items-center gap-7 rounded-lg border border-border bg-surface p-8 shadow-md max-md:p-6">
